#!/usr/bin/env python3
# =============================================================================
# install_dx.py  --  the deck export's two faults, fixed, in one install.
#
#   usage:  python install_dx.py <path-to-SIREN.html>
#
# WHAT IT INSTALLS  (three stages, one file, one atomic write)
#
#   1. THE RULE      deckPlanDiagramPages(request) -> plan.  The frame's band is
#                    RESERVED FIRST and the picture is fitted to what is left, so
#                    a title can never be painted across a flowchart again.
#                    A diagram whose height/width (2 dp) is >= 1.25 is called
#                    portrait; under that it keeps today's composed landscape
#                    slide, which is what the owner's 1.05 reference asks for.
#
#   2. THE PDF       buildRasterPdf gained a PER-PAGE /MediaBox, so a tall
#                    diagram gets its own 720x1280 portrait page - or several,
#                    cut on the gaps between blocks and labelled PART n OF m -
#                    instead of a 5%-wide ribbon down the right edge.
#
#   3. THE POWERPOINT  <p:sldSz> is written ONCE for a whole presentation, so
#                    per-slide orientation does not exist in the format.  A tall
#                    diagram is split across several LANDSCAPE slides instead and
#                    the deck stays one editable file.  Every frame shape is
#                    measured against the picture it is about to sit beside and
#                    clipped off it rather than drawn over it.
#
# SAFETY
#   * idempotent    - a file that already carries all three stages is left alone.
#   * atomic        - the target is untouched until one os.replace at the end.
#   * drift-guarded - every anchor must appear exactly once or nothing is written.
#   * refuses any target under a Downloads folder.  The live app lives there and
#     is not this installer's to rewrite; copy it out, install into the copy,
#     open the copy's exports and look at them, then move it back yourself.
# =============================================================================
import base64, hashlib, os, shutil, subprocess, sys, tempfile

