MARKERS = {
    "the rule":       "function deckPlanDiagramPages(",
    "the pdf":        "async function mapViewSlidePdfPages(view) {",
    "the powerpoint": "async function mapPptxDiagramSlides(",
}

# Shared primitives another engineer owns.  Each must still appear exactly once
# in the finished file or this install is refused.
UNTOUCHED = [
    "function buildZip(entries) {",
    "async function svgToCanvas(svgString, requestedScale, backgroundMode) {",
    "const PDF_MIN_FONT_PT = 9;",
    "function getMinimumExportFontSize() {",
    "function presentFitBox(",
    "function showToast(",
]


def die(message):
    sys.stderr.write("ABORT: " + message + "\n")
    raise SystemExit(2)


def md5_of(path):
    return hashlib.md5(open(path, "rb").read()).hexdigest()


def script_of(html):
    """The one inline <script> block, so a syntax check can see it."""
    lines = html.split("\n")
    start = end = None
    for i, line in enumerate(lines):
        if line.strip() == "<script>" and start is None:
            start = i
        if line.strip() == "</script>":
            end = i
    if start is None or end is None or end <= start:
        return None
    return "\n".join(lines[start + 1:end])


def main():
    if len(sys.argv) < 2:
        die("usage: install_dx.py <path-to-SIREN.html>")
    target = os.path.abspath(sys.argv[1])
    if not os.path.isfile(target):
        die(target + " is not a file")

    # -- the Downloads rail ---------------------------------------------------
    lowered = [p.lower() for p in os.path.normpath(target).split(os.sep)]
    if "downloads" in lowered:
        die(target + " is under a Downloads folder.\n"
            "       The live app lives there and this installer will not rewrite it.\n"
            "       Copy it elsewhere, install into the copy, open the copy's exports\n"
            "       and look at them, then move it back yourself.")

    src = open(target, "r", encoding="utf-8", newline="").read()
    before_md5 = md5_of(target)
    before_len = len(src)

    # -- idempotence ----------------------------------------------------------
    present = [name for name, token in MARKERS.items() if token in src]
    if len(present) == len(MARKERS):
        print("already installed: %s carries all three stages (md5 %s)." % (target, before_md5))
        print("nothing written.")
        return
    if present:
        die("%s carries only part of this change (%s).\n"
            "       A half-installed file is not something to patch on top of.\n"
            "       Restore the file and run this once, cleanly."
            % (target, ", ".join(sorted(present))))

    # -- everything happens on a sibling copy; the target is untouched --------
    folder = os.path.dirname(target) or "."
    handle, temp = tempfile.mkstemp(dir=folder, suffix=".dxinstall.tmp")
    os.close(handle)
    checked = "not run (node not found)"
    out = src
    try:
        shutil.copyfile(target, temp)

        for name, want_md5, payload in STAGES:
            code = base64.b64decode("".join(payload.split()))
            if hashlib.md5(code).hexdigest() != want_md5:
                die("embedded stage " + name + " is corrupt")
            namespace = {"__name__": "__main__", "__file__": name}
            saved = sys.argv[:]
            sys.argv = [name, temp]
            try:
                exec(compile(code.decode("utf-8"), name, "exec"), namespace)
            except SystemExit as stop:
                message = str(stop)
                if message and message != "0":
                    die("stage " + name + " refused: " + message)
            finally:
                sys.argv = saved

        out = open(temp, "r", encoding="utf-8", newline="").read()

        # -- post-conditions --------------------------------------------------
        for label, token in MARKERS.items():
            if out.count(token) != 1:
                die("%s did not land (%r count %d)" % (label, token, out.count(token)))
        for token in UNTOUCHED:
            if out.count(token) != 1:
                die("shared primitive %r appears %d times - not 1" % (token, out.count(token)))
        if out.count('<p:sldSz cx="${WP_PPTX.width}" cy="${WP_PPTX.height}" type="screen16x9"/>') != 2:
            die("presentation.xml no longer writes exactly one slide size")
        if out.count("/MediaBox [0 0 ${formatPdfNumber(mediaW)} ${formatPdfNumber(mediaH)}]") != 1:
            die("the raster PDF writer did not become per-page")
        if "MAP_DECK_FRAME" in out:
            die("the old frame constants survived")

        # -- syntax, if node is here to say so --------------------------------
        js = script_of(out)
        if js is None:
            die("the inline <script> block could not be found in the result")
        handle2, jstmp = tempfile.mkstemp(dir=folder, suffix=".dxcheck.js")
        with os.fdopen(handle2, "w", encoding="utf-8", newline="") as f:
            f.write(js)
        try:
            run = subprocess.run(["node", "--check", jstmp], capture_output=True, text=True)
            if run.returncode != 0:
                die("node --check failed on the result:\n" + run.stderr.strip())
            checked = "node --check OK"
        except FileNotFoundError:
            pass
        finally:
            os.unlink(jstmp)

        after_md5 = hashlib.md5(out.encode("utf-8")).hexdigest()
        if before_md5 in VERIFIED and after_md5 != VERIFIED[before_md5]:
            die("this is a base the change was verified on, but the result is not the\n"
                "       verified build (%s, expected %s).  Something drifted; nothing written."
                % (after_md5, VERIFIED[before_md5]))

        os.replace(temp, target)
        temp = None
    finally:
        if temp and os.path.exists(temp):
            os.unlink(temp)

    print("installed into " + target)
    print("  %d -> %d characters (%+d)" % (before_len, len(out), len(out) - before_len))
    print("  md5 %s -> %s" % (before_md5, md5_of(target)))
    print("  stages: " + ", ".join(name for name, _, _ in STAGES))
    print("  syntax: " + checked)
    if before_md5 in VERIFIED:
        print("  this is one of the bases the change was driven and read on, and the")
        print("  result is byte-identical to the build whose exports were opened.")
    else:
        print("  this base is newer than the ones the change was read on; the anchors")
        print("  all matched, so it is installed, but no fingerprint could be checked.")


if __name__ == "__main__":
    main()
